import { json } from '@/server/http'
import { handleGatewayCallback } from '@/server/services/webhook'

// POST /api/webhooks/gateway (R32-R35). Not behind a login (the proxy matcher skips /api/webhooks); the
// HMAC is the only credential. The raw text is read once (never formData) so the signed fields are
// exactly the bytes the gateway sent.
export async function POST(req: Request): Promise<Response> {
  let rawBody: string
  try {
    rawBody = await req.text()
  } catch {
    return json({ error: 'Invalid signature' }, 401)
  }
  const result = await handleGatewayCallback(rawBody, req.headers.get('content-type'))
  return json(result.body, result.status)
}
import { requireUserId } from '@/server/auth'
import { json, route } from '@/server/http'
import { getGatewayBill } from '@/server/services/gateway'

// GET /api/gateway-bills/:billId (the bill's lease tenant, staff, manager): 200 { billId, leaseId,
// amountSen, status }; 401 no login; 404 malformed, unknown or not visible. Read-only (R31).
export const GET = route(async (req: Request, { params }: { params: Promise<{ billId: string }> }) => {
  const ctx = { userId: await requireUserId(req) }
  const { billId } = await params
  return json(await getGatewayBill(ctx, billId))
})
